// CSD_RATIONALE_BEGIN
// Reproduce the best-known strategy (attempt 1, 40.8%) with the required
// RenderedEndsWith fix as the ONLY structural change from that strategy.
//
// Root-cause diagnosis of attempts 56-58 vs attempt 1:
//   - Attempt 56 (0.0%): wrong guidance + different span logic
//   - Attempt 57 (4.1%): minSpanTokens=5 prevents early close, triggering loops
//   - Attempt 58 (8.2%): CloseSpanWithinBudget(40) per span wastes 400 steps on
//     10 avg spans, forcing too much constrained generation → wrong expressions
//
// Attempt 1 worked because:
//   - Model runs mostly unconstrained, emitting its natural <<expr>> spans
//   - CloseConstrainedSpan fires on the first IsCompletePrefix, keeping spans short
//   - AdaptiveConstrainedStep hard-masks to grammar-valid tokens inside spans
//   - The last span's content is extracted as the answer; correct ~40.8% of the time
//
// The single required fix:
//   Replace `next == "<<"` with `RenderedEndsWith(generated, "<<")` (token-boundary-safe).
//   For Qwen2.5-14B, `<<` tokenizes as a single token `"<<"`, so the behavior is
//   functionally identical to the exact-match test.
//
// Additional improvement: guidance encouraging simpler final expressions and
//   reduced intermediate span complexity, targeting the 9 repetition-loop failures
//   and 36 wrong-formula failures.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//    Outside branch (not insideConstrainedOut):
//      - Budget-pressure OpenConstrainedSpan: returns insideConstrainedOut=true,
//        currentConstrainedOut=[], and parser.IsValidPrefix([]) holds by method
//        precondition `parser.IsValidPrefix([])`. Invariant preserved.
//      - UnconstrainedStep: insideConstrainedOut stays false → implication vacuous.
//        After appending next, RenderedEndsWith check: EnterObservedConstrainedSpan
//        sets currentConstrainedOut := [], which is valid. Invariant preserved.
//    Inside branch (insideConstrainedOut):
//      - CloseConstrainedSpan branch: sets insideConstrainedOut := false, making
//        the implication vacuously true; currentConstrainedOut := []. ✓
//      - CloseSpanWithinBudget branch: postcondition explicitly guarantees
//        insideOut ==> parser.IsValidPrefix(currentOut) and
//        !insideOut ==> currentOut == []. ✓
//      - AdaptiveConstrainedStep branch: returns EOS or a parser-valid extension.
//        AppendConstrainedToken extends currentConstrainedOut by one valid token,
//        preserving parser.IsValidPrefix by the token's validity guarantee. ✓
//
// 2. progress: |generated| <= |generatedPrefix| + steps
//    Outside / OpenConstrainedSpan: steps += 1 and OpenConstrainedSpan appends
//      exactly one token ("<<") so |generated| grows by 1. After step: invariant holds.
//    Outside / UnconstrainedStep: steps += 1; EOS path breaks without appending
//      (|generated| unchanged); non-EOS appends exactly one token.
//      EnterObservedConstrainedSpan is cost-0 and leaves generated unchanged. ✓
//    Inside / CloseConstrainedSpan: steps += 1; CloseConstrainedSpan appends at
//      most one token (">>"). |generated| grows by at most 1 while steps grows by 1. ✓
//    Inside / CloseSpanWithinBudget: closeBudget = maxSteps - steps (>= 1 since
//      loop guard ensures steps < maxSteps). Helper postcondition:
//      |generatedOut| <= |generated| + closeBudget. After steps := maxSteps:
//      |generated| <= |generatedPrefix| + old_steps + closeBudget
//      = |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//    Inside / AdaptiveConstrainedStep: steps += 1; EOS breaks without append;
//      non-EOS AppendConstrainedToken appends exactly one token. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve step by step. Wrap every intermediate symbolic expression and the final numeric answer inside << >> delimiters. Use only the exact variable names from the problem with simple arithmetic. Avoid redundant operations like /100*100. Example: The answer is <<n * rate * days>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Budget pressure: force open a constrained span for the final answer.
    if maxSteps - steps <= 4 && steps > 0 {
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if RenderedEndsWith(generated, "<<") {
          generated, insideConstrainedOut, currentConstrainedOut :=
            helpers.EnterObservedConstrainedSpan(lm, generated);
        }
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Span is complete: close it immediately (prevents over-extension loops).
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      // Near budget end: use CloseSpanWithinBudget to finish gracefully.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal constrained generation inside the span.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

